        </section>

        <section className="space-y-4">
          <SectionHeader title="Follow-up" description="Pending actions and reminders" />
          <PendingActionTracker />
        </section>

        <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
          <Card>
            <CardHeader>
              <SectionHeader icon={BookOpen} title="Recent work logs" description="Work" />
            </CardHeader>
            <CardContent>
              {recentLogs.length > 0 ? (
                <div className="space-y-3">
                  {recentLogs.map((log) => (
                    <div key={log.id} className="flex items-start justify-between rounded-xl border border-slate-100 bg-slate-50/80 p-3 dark:border-slate-800 dark:bg-slate-900/50">
                      <div className="flex-1">
                        <p className="font-medium text-sm">{log.description}</p>
                        <div className="flex items-center gap-2 mt-1">
                          <Badge variant="outline" className="text-xs">
                            {log.category}
                          </Badge>
                          <span className="text-xs text-muted-foreground">
                            {format(new Date(log.date), 'MMM d')}
                          </span>
                          <span className="text-xs text-muted-foreground">
                            {Math.round(log.duration / 60 * 10) / 10}h
                          </span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-4">
                  <p className="text-muted-foreground mb-3">
                    No work logs yet. Capture the next useful support action.
                  </p>
                  <Button size="sm" asChild>
                    <Link href="/work-logs">Create Work Log</Link>
                  </Button>
                </div>
              )}
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <SectionHeader icon={CheckSquare} title="Pending tasks" />
            </CardHeader>
            <CardContent>
              {pendingTasks.length > 0 ? (
                <div className="space-y-3">
                  {pendingTasks.map((task) => {
                    const overdue = task.dueDate && isPast(new Date(task.dueDate));
                    return (
                    <div
                      key={task.id}
                      className={`flex items-start justify-between gap-2 rounded-xl border p-3 ${
                        overdue
                          ? 'border-amber-300/80 bg-amber-50/80 dark:border-amber-800 dark:bg-amber-950/30'
                          : 'border-slate-100 bg-slate-50/80 dark:border-slate-700 dark:bg-slate-900/50'
                      }`}
                    >
                      <div className="flex-1">
                        <p className="font-medium text-sm text-slate-900 dark:text-white">{task.title}</p>
                        <div className="mt-1 flex flex-wrap items-center gap-2">
                          <Badge variant={getPriorityColor(task.priority)} className="text-xs">
                            {task.priority}
                          </Badge>
                          <Badge variant="outline" className="text-xs">
                            {task.category}
                          </Badge>
                          {task.dueDate && (
                            <span className={`text-xs ${overdue ? 'font-medium text-amber-700 dark:text-amber-300' : 'text-muted-foreground'}`}>
                              Due {format(new Date(task.dueDate), 'MMM d')}
                            </span>
                          )}
                        </div>
                      </div>
                      <Button size="sm" variant="outline" className="shrink-0 text-xs" onClick={() => markTaskDone(task.id)}>
                        Done
                      </Button>
                    </div>
                  );
                  })}
                </div>
              ) : (
                <p className="text-muted-foreground text-center py-4">
                  No pending tasks. Great job staying on top of things!
                </p>
              )}
            </CardContent>
          </Card>
        </div>

        <EducationalGamesSection />
    </PageShell>
  );
}

